    10→/**
    11→ * Repository is a high level kv storage
    12→ * This abstract repository is designed in a way to store items with different prefixed
    13→ * Specially when those prefixed data is not available in the object to be stored
    14→ *
    15→ * By default, SSZ-encoded values,
    16→ */
    17→export abstract class PrefixedRepository<P, I extends Id, T> {
    18→  private readonly dbReqOpts: DbReqOpts;
    19→  /** Inclusive range for the minimum key for the bucket */
    20→  private readonly minKey: Uint8Array;
    21→  /** Exclusive range for the maximum key for the bucket */
    22→  private readonly maxKey: Uint8Array;
    23→
    24→  protected constructor(
    25→    protected config: ChainForkConfig,
    26→    protected db: Db,
    27→    protected bucket: number,
    28→    protected type: Type<T>,
    29→    private readonly bucketId: string
    30→  ) {
    31→    this.dbReqOpts = {bucketId: this.bucketId};
    32→    this.minKey = encodeKey(bucket, Buffer.alloc(0));
    33→    this.maxKey = encodeKey(bucket + 1, Buffer.alloc(0));
    34→  }
    35→
    36→  abstract encodeKeyRaw(prefix: P, id: I): Uint8Array;
    37→  abstract decodeKeyRaw(raw: Uint8Array): {prefix: P; id: I};
    38→  /**
    39→   * Max key is inclusive
    40→   * */
    41→  abstract getMaxKeyRaw(prefix: P): Uint8Array;
    42→  /**
    43→   * Min key is inclusive
    44→   * */
    45→  abstract getMinKeyRaw(prefix: P): Uint8Array;
    46→
    47→  protected encodeValue(value: T): Uint8Array {
    48→    return this.type.serialize(value);
    49→  }
    50→
    51→  protected decodeValue(data: Uint8Array): T {
    52→    return this.type.deserialize(data);
    53→  }
    54→
    55→  protected wrapKey(raw: Uint8Array): Uint8Array {
    56→    return encodeKey(this.bucket, raw);
    57→  }
    58→
    59→  protected unwrapKey(key: Uint8Array): Uint8Array {
    60→    return key.slice(BUCKET_LENGTH);
    61→  }
    62→
    63→  // The Id can be inferred from the value
    64→  getId(value: T): I {
    65→    return this.type.hashTreeRoot(value) as I;
    66→  }
    67→
    68→  async get(prefix: P, id: I): Promise<T | null> {
    69→    const key = this.wrapKey(this.encodeKeyRaw(prefix, id));
    70→    const v = await this.db.get(key, this.dbReqOpts);
    71→    return v ? this.decodeValue(v) : null;
    72→  }
    73→
    74→  async getMany(prefix: P, ids: I[]): Promise<(T | undefined)[]> {
    75→    const keys = [];
    76→    for (const id of ids) {
    77→      keys.push(this.wrapKey(this.encodeKeyRaw(prefix, id)));
    78→    }
    79→    const values = await this.db.getMany(keys, this.dbReqOpts);
    80→
    81→    const result = [];
    82→    for (const value of values) {
    83→      result.push(value ? this.decodeValue(value) : undefined);
    84→    }
    85→
    86→    return result;
    87→  }
    88→
    89→  async getManyBinary(prefix: P, ids: I[]): Promise<(Uint8Array | undefined)[]> {
    90→    const keys = [];
    91→    for (const id of ids) {
    92→      keys.push(this.wrapKey(this.encodeKeyRaw(prefix, id)));
    93→    }
    94→    return await this.db.getMany(keys, this.dbReqOpts);
    95→  }
    96→
    97→  async getBinary(prefix: P, id: I): Promise<Uint8Array | null> {
    98→    const key = this.wrapKey(this.encodeKeyRaw(prefix, id));
    99→    return await this.db.get(key, this.dbReqOpts);
   100→  }
   101→
   102→  async put(prefix: P, item: T): Promise<void> {
   103→    const id = this.getId(item);
   104→    const key = this.wrapKey(this.encodeKeyRaw(prefix, id));
   105→    await this.db.put(key, this.encodeValue(item), this.dbReqOpts);
   106→  }
   107→
   108→  async putMany(prefix: P, items: T[]): Promise<void> {
   109→    const batch: KeyValue<Uint8Array, Uint8Array>[] = [];
   110→    for (const item of items) {
   111→      const id = this.getId(item);
   112→      const key = this.wrapKey(this.encodeKeyRaw(prefix, id));
   113→      batch.push({key, value: this.encodeValue(item)});
   114→    }
   115→    await this.db.batchPut(batch, this.dbReqOpts);
   116→  }
   117→
   118→  async putBinary(prefix: P, id: I, bytes: Uint8Array): Promise<void> {
   119→    const key = this.wrapKey(this.encodeKeyRaw(prefix, id));
   120→    await this.db.put(key, bytes, this.dbReqOpts);
   121→  }
   122→
   123→  async putManyBinary(prefix: P, items: KeyValue<I, Uint8Array>[]): Promise<void> {
   124→    const batch: KeyValue<Uint8Array, Uint8Array>[] = [];
   125→    for (const {key, value} of items) {
   126→      batch.push({key: this.wrapKey(this.encodeKeyRaw(prefix, key)), value: value});
   127→    }
   128→    await this.db.batchPut(batch, this.dbReqOpts);
   129→  }
   130→
   131→  async delete(prefix: P, id: I): Promise<void> {
   132→    const key = this.wrapKey(this.encodeKeyRaw(prefix, id));
   133→    await this.db.delete(key, this.dbReqOpts);
   134→  }
   135→
   136→  async deleteMany(prefix: P | P[]): Promise<void> {
   137→    const keys: Uint8Array[][] = [];
   138→
   139→    for (const p of Array.isArray(prefix) ? prefix : [prefix]) {
   140→      const prefixedKeys = await this.db.keys({
   141→        gte: this.wrapKey(this.getMinKeyRaw(p)),
   142→        lte: this.wrapKey(this.getMaxKeyRaw(p)),
   143→        bucketId: this.bucketId,
