   200→    for (const v of Array.isArray(prefix) ? prefix : [prefix]) {
   201→      for await (const {key, value} of this.db.entriesStream({
   202→        gte: this.wrapKey(this.getMinKeyRaw(v)),
   203→        lte: this.wrapKey(this.getMaxKeyRaw(v)),
   204→        bucketId: this.bucketId,
